\u0631 \u0641\u064a \u0627\u0644\u0645\u064a\u0644 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641 \u062d\u062a\u0649 \u062a\u0634\u0639\u0631 \u0628\u062a\u0645\u062f\u062f \u0641\u064a \u0639\u0645\u0648\u062f\u0643 \u0627\u0644\u0641\u0642\u0631\u064a.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u0645\u062f\u062f \u0644\u0628\u0636\u0639 \u062b\u0648\u0627\u0646\u060c \u062b\u0645 \u0639\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1363","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"spine","secondary_muscles":["hamstrings","glutes"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1363-JbC2iaV.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1363-JbC2iaV.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"c2e48d4b-bdcb-5375-82f2-8823abf4d9c8","source_id":"2329","name_en":"spine twist","name_ar":"\u062a\u0637\u0648\u0631 \u0627\u0644\u0639\u0645\u0648\u062f \u0627\u0644\u0641\u0642\u0631\u064a","match_names":["spine twist"],"muscle":"core","equipment":"bodyweight","aliases":["spine twist"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Sit on the ground with your legs extended in front of you.\nBend your knees and place your feet flat on the ground, hip-width apart.\nPlace your hands behind your head with your elbows pointing outwards.\nEngage your abs and slowly twist your torso to the right, bringing your right elbow towards your left knee.\nPause for a moment at the end of the twist, then slowly return to the starting position.\nRepeat the twist to the left side, bringing your left elbow towards your right knee.\nContinue alternating sides for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0645\u0639 \u0645\u062f \u0633\u0627\u0642\u064a\u0643 \u0623\u0645\u0627\u0645\u0643.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u064a\u0643\u060c \u0648\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629\u0647\u0645\u0627 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0648\u0631\u0643\u064a\u0646.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u062e\u0644\u0641 \u0631\u0623\u0633\u0643 \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0645\u0631\u0641\u0642\u064a\u0643 \u0644\u0644\u062e\u0627\u0631\u062c.\n\u0642\u0645 \u0628\u062a\u0634\u063a\u064a\u0644 \u0639\u0636\u0644\u0627\u062a \u0628\u0637\u0646\u0643 \u0648\u0642\u0645 \u0628\u062a\u062d\u0631\u064a\u0641 \u062c\u0630\u0639\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0627\u0644\u064a\u0645\u064a\u0646\u060c \u0628\u062d\u064a\u062b \u064a\u0635\u0644 \u0645\u0631\u0641\u0642\u0643 \u0627\u0644\u0623\u064a\u0645\u0646 \u0646\u062d\u0648 \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u064a\u0633\u0631\u0649.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0639\u0646\u062f \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u0627\u0644\u062a\u0648\u0627\u0621\u060c \u062b\u0645 \u0639\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0627\u0644\u062a\u0648\u0627\u0621 \u0639\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0623\u064a\u0633\u0631\u060c \u0645\u0639 \u0631\u0641\u0639 \u0643\u0648\u0639\u0643 \u0627\u0644\u0623\u064a\u0633\u0631 \u0646\u062d\u0648 \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u064a\u0645\u0646\u0649.\n\u0627\u0633\u062a\u0645\u0631 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0628\u064a\u0646 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"2329","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["obliques","lower back"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/2329-2jl9K55.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/2329-2jl9K55.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"257488ed-4f64-5909-852b-7161ea8a03c8","source_id":"2368","name_en":"split squats","name_ar":"\u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0627\u0644\u0645\u0642\u0633\u0645\u0629","match_names":["split squats"],"muscle":"quads","equipment":"bodyweight","aliases":["split squats"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart.\nTake a step forward with one foot and place it about two feet in front of the other foot.\nLower your body by bending your knees and hips, keeping your back straight.\nContinue lowering until your front thigh is parallel to the ground, and your back knee is hovering just above the ground.\nPause for a moment, then push through your front heel to return to the starting position.\nRepeat for the desired number of repetitions, then switch legs and repeat.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u062e\u0630 \u062e\u0637\u0648\u0629 \u0644\u0644\u0623\u0645\u0627\u0645 \u0628\u0642\u062f\u0645 \u0648\u0627\u062d\u062f\u0629 \u0648\u0636\u0639\u0647\u0627 \u0639\u0644\u0649 \u0628\u0639\u062f \u062d\u0648\u0627\u0644\u064a \u0642\u062f\u0645\u064a\u0646 \u0623\u0645\u0627\u0645 \u0627\u0644\u0642\u062f\u0645 \u0627\u0644\u0623\u062e\u0631\u0649.\n\u0627\u062e\u0641\u0636\u064a \u062c\u0633\u0645\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0627\u0644\u0631\u0643\u0628\u062a\u064a\u0646 \u0648\u0627\u0644\u0648\u0631\u0643\u064a\u0646\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0627\u0644\u0638\u0647\u0631.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0627\u0646\u062e\u0641\u0627\u0636 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0641\u062e\u0630\u0643 \u0627\u0644\u0623\u0645\u0627\u0645\u064a \u0645\u0648\u0627\u0632\u064a\u064b\u0627 \u0644\u0644\u0623\u0631\u0636\u060c \u0648\u062a\u062d\u0648\u0645 \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u062e\u0644\u0641\u064a\u0629 \u0641\u0648\u0642 \u0627\u0644\u0623\u0631\u0636 \u0645\u0628\u0627\u0634\u0631\u0629\u064b.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0627\u062f\u0641\u0639 \u0645\u0646 \u062e\u0644\u0627\u0644 \u0643\u0639\u0628\u0643 \u0627\u0644\u0623\u0645\u0627\u0645\u064a \u0644\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0628\u062f\u0644 \u0627\u0644\u0633\u0627\u0642\u064a\u0646 \u0648\u0643\u0631\u0631 \u0627\u0644\u0623\u0645\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"2368","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"quads","secondary_muscles":["glutes","hamstrings","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/2368-9E25EOx.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/2368-9E25EOx.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"f76fb9ec-b3f1-5336-8e41-736244dd7923","source_id":"0786","name_en":"squat jerk","name_ar":"\u0631\u0639\u0634\u0629 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621","match_names":["squat jerk"],"muscle":"quads","equipment":"barbell","aliases":["squat jerk"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Start with the barbell resting on your shoulders, with your feet shoulder-width apart.\nLower your body into a squat position, keeping your chest up and your knees tracking over your toes.\nAs you reach the bottom of the squat, explosively drive through your legs and push the barbell overhead.\nAs the barbell reaches its peak, quickly drop into a split position, with one foot forward and one foot back.\nCatch the barbell overhead with your arms fully extended and your back knee slightly touching the ground.\nStand up from the split position, bringing your feet back together.\nLower the barbell back to your shoulders and repeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0648\u0636\u0639 \u0627\u0644\u062d\u062f\u064a\u062f \u0639\u0644\u0649 \u0643\u062a\u0641\u064a\u0643\u060c \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0627\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0635\u062f\u0631\u0643 \u0645\u0631\u062a\u0641\u0639\u064b\u0627 \u0648\u0631\u0643\u0628\u062a\u064a\u0643 \u0639\u0644\u0649 \u0623\u0635\u0627\u0628\u0639 \u0642\u062f\u0645\u064a\u0643.\n\u0639\u0646\u062f\u0645\u0627 \u062a\u0635\u0644 \u0625\u0644\u0649 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0633\u0641\u0644\u064a \u0645\u0646 \u062a\u0645\u0631\u064a\u0646 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621\u060c \u0642\u0645 \u0628\u0627\u0644\u0642\u064a\u0627\u062f\u0629 \u0628\u0634\u0643\u0644 \u0645\u062a\u0641\u062c\u0631 \u0639\u0628\u0631 \u0633\u0627\u0642\u064a\u0643 \u0648\u0627\u062f\u0641\u0639 \u0627\u0644\u062d\u062f\u064a\u062f \u0641\u0648\u0642 \u0631\u0623\u0633\u0643.\n\u0639\u0646\u062f\u0645\u0627 \u064a\u0635\u0644 \u0627\u0644\u062d\u062f\u064a\u062f \u0625\u0644\u0649 \u0630\u0631\u0648\u062a\u0647\u060c \u0627\u0646\u0632\u0644 \u0628\u0633\u0631\u0639\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u0642\u0633\u0627\u0645\u060c \u0645\u0639 \u0642\u062f\u0645 \u0648\u0627\u062d\u062f\u0629 \u0644\u0644\u0623\u0645\u0627\u0645 \u0648\u0642\u062f\u0645 \u0648\u0627\u062d\u062f\u0629 \u0644\u0644\u062e\u0644\u0641.\n\u0623\u0645\u0633\u0643 \u0628\u0627\u0644\u062d\u062f\u064a\u062f \u0641\u0648\u0642 \u0631\u0623\u0633\u0643 \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0648\u0644\u0645\u0633 \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u062e\u0644\u0641\u064a\u0629 \u0627\u0644\u0623\u0631\u0636 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0642\u0641 \u0645\u0646 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u0642\u0633\u0627\u0645\u060c \u0648\u0627\u062c\u0645\u0639 \u0642\u062f\u0645\u064a\u0643 \u0645\u0639\u064b\u0627 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649.\n\u0623\u0646\u0632\u0644 \u0627\u0644\u062d\u062f\u064a\u062f \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0643\u062a\u0641\u064a\u0643 \u0648\u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0786","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"quads","secondary_muscles":["glutes","hamstrings","calves","core"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0786-IMRsOCn.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0786-IMRsOCn.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"cfd52e4e-46f7-502c-8bb1-cba75500d295","source_id":"1705","name_en":"squat on bosu ball","name_ar":"\u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0639\u0644\u0649 \u0643\u0631\u0629 \u0628\u0648\u0633\u0648","match_names":["squat on bosu ball"],"muscle":"quads","equipment":"bosu_ball","aliases":["squat on bosu ball"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Place the bosu ball on the ground with the flat side up.\nStand with your feet shoulder-width apart and position yourself on top of the bosu ball.\nLower your body down by bending your knees and hips, as if sitting back into a chair.\nKeep your chest up and your weight on your heels.\nLower yourself until your thighs are parallel to the ground.\nPause for a moment, then push through your heels to return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0636\u0639 \u0643\u0631\u0629 \u0627\u0644\u0628\u0648\u0633\u0648 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0628\u062d\u064a\u062b \u064a\u0643\u0648\u0646 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0645\u0633\u0637\u062d \u0644\u0623\u0639\u0644\u0649.\n\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u062b\u0645 \u0636\u0639 \u0646\u0641\u0633\u0643 \u0641\u0648\u0642 \u0643\u0631\u0629 \u0627\u0644\u0628\u0648\u0633\u0648.\n\u0627\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0625\u0644\u0649 \u0627\u0644\u0623\u0633\u0641\u0644 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u0648\u0631\u0643\u064a\u0643\u060c \u0643\u0645\u0627 \u0644\u0648 \u0643\u0646\u062a \u062a\u062c\u0644\u0633 \u0639\u0644\u0649 \u0643\u0631\u0633\u064a.\n\u0623\u0628\u0642\u0650 \u0635\u062f\u0631\u0643 \u0645\u0631\u062a\u0641\u0639\u064b\u0627 \u0648\u0648\u0632\u0646\u0643 \u0639\u0644\u0649 \u0643\u0639\u0628\u064a\u0643.\n\u0627\u062e\u0641\u0636 \u0646\u0641\u0633\u0643 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0641\u062e\u0630\u064a\u0643 \u0645\u0648\u0627\u0632\u064a\u064a\u0646 \u0644\u0644\u0623\u0631\u0636.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0627\u062f\u0641\u0639 \u0643\u0639\u0628\u064a\u0643 \u0644\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1705","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"quads","secondary_muscles":["glutes","hamstrings","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1705-T2fA5Ir.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1705-T2fA5Ir.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"286f0caf-cc96-5baa-8f11-b5330c5e6cd7","source_id":"1685","name_en":"squat to overhead reach","name_ar":"\u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0644\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0627\u0644\u0646\u0641\u0642\u0627\u062a \u0627\u0644\u0639\u0627\u0645\u0629","match_names":["squat to overhead reach"],"muscle":"quads","equipment":"bodyweight","aliases":["squat to overhead reach"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart and toes slightly turned out.\nLower your body down into a squat position by bending your knees and pushing your hips back.\nAs you come up from the squat, extend your arms overhead, reaching towards the ceiling.\nReturn to the starting position by lowering your arms and bending your knees to squat down again.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u0625\u062e\u0631\u0627\u062c \u0623\u0635\u0627\u0628\u0639 \u0642\u062f\u0645\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0623\u0646\u0632\u0644 \u062c\u0633\u0645\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u062f\u0641\u0639 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641.\n\u0639\u0646\u062f \u0635\u0639\u0648\u062f\u0643 \u0645\u0646 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621\u060c \u0642\u0645 \u0628\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0641\u0648\u0642 \u0631\u0623\u0633\u0643\u060c \u062d\u062a\u0649 \u062a\u0635\u0644 \u0625\u0644\u0649 \u0627\u0644\u0633\u0642\u0641.\n\u0627\u0631\u062c\u0639 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0639\u0646 \u0637\u0631\u064a\u0642 \u