45\u0629 \u0638\u0647\u0631\u0643 \u0648\u0646\u0634\u0627\u0637\u0643 \u0627\u0644\u0623\u0633\u0627\u0633\u064a.\n\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u062d\u062f\u064a\u062f \u0623\u0639\u0644\u0649 \u0631\u0623\u0633\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0648\u0645\u062f \u0645\u0631\u0641\u0642\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u062d\u062f\u064a\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0788","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["triceps","upper back"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0788-xDh0lJr.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0788-xDh0lJr.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"4d9f4d32-1fdd-5f5e-894a-b9689787acac","source_id":"1490","name_en":"standing calf raise (on a staircase)","name_ar":"\u0631\u0641\u0639 \u0627\u0644\u0639\u062c\u0644 \u0648\u0627\u0642\u0641\u0627\u064b (\u0639\u0644\u0649 \u0627\u0644\u062f\u0631\u062c)","match_names":["standing calf raise (on a staircase)"],"muscle":"calves","equipment":"bodyweight","aliases":["standing calf raise (on a staircase)"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand on the edge of a step or a sturdy platform with your heels hanging off and your toes on the step.\nHold onto a railing or wall for balance if needed.\nSlowly raise your heels as high as possible, lifting your body weight onto the balls of your feet.\nPause for a moment at the top, then slowly lower your heels back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0639\u0644\u0649 \u062d\u0627\u0641\u0629 \u062f\u0631\u062c\u0629 \u0623\u0648 \u0645\u0646\u0635\u0629 \u0645\u062a\u064a\u0646\u0629 \u0645\u0639 \u062a\u0639\u0644\u064a\u0642 \u0643\u0639\u0628\u064a\u0643 \u0648\u0623\u0635\u0627\u0628\u0639 \u0642\u062f\u0645\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u062f\u0631\u062c\u0629.\n\u062a\u0645\u0633\u0643 \u0628\u062f\u0631\u0627\u0628\u0632\u064a\u0646 \u0623\u0648 \u062c\u062f\u0627\u0631 \u0644\u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u062a\u0648\u0627\u0632\u0646 \u0625\u0630\u0627 \u0644\u0632\u0645 \u0627\u0644\u0623\u0645\u0631.\n\u0627\u0631\u0641\u0639\u064a \u0643\u0639\u0628\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0623\u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0645\u0645\u0643\u0646\u060c \u0645\u0639 \u0631\u0641\u0639 \u0648\u0632\u0646 \u062c\u0633\u0645\u0643 \u0639\u0644\u0649 \u0645\u0634\u0637 \u0642\u062f\u0645\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0643\u0639\u0628\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1490","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"calves","secondary_muscles":["ankles","feet"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1490-6HmFgmx.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1490-6HmFgmx.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"a8d7e1f2-9754-574c-81d5-eeb5bf2f3ed6","source_id":"1397","name_en":"standing calves","name_ar":"\u0627\u0644\u0639\u062c\u0648\u0644 \u0627\u0644\u062f\u0627\u0626\u0645\u0629","match_names":["standing calves"],"muscle":"calves","equipment":"bodyweight","aliases":["standing calves"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart, toes pointing forward.\nRaise your heels off the ground as high as possible, standing on your toes.\nHold the position for a moment, then slowly lower your heels back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u062a\u0648\u062c\u064a\u0647 \u0623\u0635\u0627\u0628\u0639 \u0642\u062f\u0645\u064a\u0643 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u0627\u0631\u0641\u0639\u064a \u0643\u0639\u0628\u064a\u0643 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636 \u0625\u0644\u0649 \u0623\u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0645\u0645\u0643\u0646\u060c \u0648\u0627\u0642\u0641\u0629 \u0639\u0644\u0649 \u0623\u0635\u0627\u0628\u0639 \u0642\u062f\u0645\u064a\u0643.\n\u062b\u0628\u062a\u064a \u0647\u0630\u0627 \u0627\u0644\u0648\u0636\u0639 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0623\u0646\u0632\u0644\u064a \u0643\u0639\u0628\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1397","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"calves","secondary_muscles":["hamstrings","glutes"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1397-XIHEoCG.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1397-XIHEoCG.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"5bacfd5d-c845-5fdf-8578-adc1c92efdf8","source_id":"1398","name_en":"standing calves calf stretch","name_ar":"\u0627\u0644\u0639\u062c\u0648\u0644 \u0627\u0644\u062f\u0627\u0626\u0645\u0629 \u062a\u0645\u062a\u062f \u0627\u0644\u0639\u062c\u0644","match_names":["standing calves calf stretch"],"muscle":"calves","equipment":"bodyweight","aliases":["standing calves calf stretch"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Stand facing a wall or sturdy object, about an arm''s length away.\nPlace your hands on the wall or object at shoulder height.\nStep back with one foot, keeping your heel flat on the ground.\nBend your front knee slightly and lean forward, keeping your back leg straight.\nYou should feel a stretch in your calf muscle.\nHold the stretch for 20-30 seconds.\nRepeat on the other leg.","steps_ar":"\u0642\u0641 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u062c\u062f\u0627\u0631 \u0623\u0648 \u062c\u0633\u0645 \u0642\u0648\u064a\u060c \u0639\u0644\u0649 \u0645\u0633\u0627\u0641\u0629 \u0630\u0631\u0627\u0639 \u062a\u0642\u0631\u064a\u0628\u064b\u0627.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u062d\u0627\u0626\u0637 \u0623\u0648 \u0627\u0644\u062c\u0633\u0645 \u0639\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0643\u062a\u0641.\n\u0639\u062f \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641 \u0628\u0642\u062f\u0645 \u0648\u0627\u062d\u062f\u0629\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0643\u0639\u0628\u0643 \u0645\u0633\u0637\u062d\u064b\u0627 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u0623\u0645\u0627\u0645\u064a\u0629 \u0642\u0644\u064a\u0644\u064b\u0627 \u0648\u0627\u0646\u062d\u0646\u0650 \u0644\u0644\u0623\u0645\u0627\u0645\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0633\u0627\u0642\u0643 \u0627\u0644\u062e\u0644\u0641\u064a\u0629.\n\u064a\u062c\u0628 \u0623\u0646 \u062a\u0634\u0639\u0631 \u0628\u062a\u0645\u062f\u062f \u0641\u064a \u0639\u0636\u0644\u0629 \u0627\u0644\u0633\u0627\u0642.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u