644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1364","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"spine","secondary_muscles":["abdominals"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1364-cuKYxhu.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1364-cuKYxhu.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"bdab966a-c671-5d25-826f-c5f13385fa5a","source_id":"0795","name_en":"standing single leg curl","name_ar":"\u064a\u0642\u0641 \u062d\u0644\u064a\u0642\u0629 \u0633\u0627\u0642 \u0648\u0627\u062d\u062f\u0629","match_names":["standing single leg curl"],"muscle":"hamstrings","equipment":"bodyweight","aliases":["standing single leg curl"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet hip-width apart and your hands on your hips.\nShift your weight onto your left leg and lift your right foot off the ground, bending your knee.\nSlowly curl your right heel towards your glutes, squeezing your hamstring.\nPause for a moment at the top, then slowly lower your right foot back down to the starting position.\nRepeat for the desired number of repetitions, then switch legs.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0648\u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0648\u0631\u0643\u064a\u0643.\n\u0627\u0646\u0642\u0644 \u0648\u0632\u0646\u0643 \u0625\u0644\u0649 \u0633\u0627\u0642\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0648\u0627\u0631\u0641\u0639 \u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u0643.\n\u0642\u0645 \u0628\u0644\u0641 \u0643\u0639\u0628\u0643 \u0627\u0644\u0623\u064a\u0645\u0646 \u0628\u0628\u0637\u0621 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u062f\u0627\u0641\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0623\u0648\u062a\u0627\u0631 \u0627\u0644\u0631\u0643\u0628\u0629.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0645\u0639 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0642\u0645 \u0628\u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0633\u0627\u0642\u064a\u0646.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0795","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"hamstrings","secondary_muscles":["glutes"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0795-C5jncD2.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0795-C5jncD2.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"7d158da9-9b56-50fc-89b3-35fdcb847b45","source_id":"0796","name_en":"standing wheel rollerout","name_ar":"\u062f\u0648\u0631\u0627\u0646 \u0627\u0644\u0639\u062c\u0644\u0629 \u0627\u0644\u062f\u0627\u0626\u0645\u0629","match_names":["standing wheel rollerout"],"muscle":"core","equipment":"wheel_roller","aliases":["standing wheel rollerout"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Start by standing tall with your feet shoulder-width apart and the wheel roller in front of you.\nBend at your waist and slowly roll the wheel forward, keeping your back straight and your core engaged.\nContinue rolling forward until you feel a stretch in your abs and your body is extended as far as possible.\nPause for a moment, then slowly roll the wheel back towards your body, returning to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0627\u0644\u0648\u0642\u0648\u0641 \u0637\u0648\u064a\u0644\u064b\u0627 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u0628\u0643\u0631\u0629 \u0627\u0644\u0639\u062c\u0644\u0629 \u0623\u0645\u0627\u0645\u0643.\n\u0627\u0646\u062d\u0646\u0649 \u0639\u0646\u062f \u062e\u0635\u0631\u0643 \u0648\u0642\u0645 \u0628\u062a\u062d\u0631\u064a\u0643 \u0627\u0644\u0639\u062c\u0644\u0629 \u0628\u0628\u0637\u0621 \u0644\u0644\u0623\u0645\u0627\u0645\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u062c\u0630\u0628 \u062c\u0630\u0639\u0643.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u062f\u062d\u0631\u062c \u0644\u0644\u0623\u0645\u0627\u0645 \u062d\u062a\u0649 \u062a\u0634\u0639\u0631 \u0628\u062a\u0645\u062f\u062f \u0641\u064a \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0628\u0637\u0646 \u0648\u064a\u0645\u062a\u062f \u062c\u0633\u0645\u0643 \u0625\u0644\u0649 \u0623\u0642\u0635\u0649 \u062d\u062f \u0645\u0645\u0643\u0646.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0623\u062f\u0631 \u0627\u0644\u0639\u062c\u0644\u0629 \u0628\u0628\u0637\u0621 \u0646\u062d\u0648 \u062c\u0633\u0645\u0643\u060c \u062b\u0645 \u0639\u062f \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0796","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["lower back","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0796-KtRomty.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0796-KtRomty.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"40b98a59-96c8-5232-8fca-565e7ddef390","source_id":"3223","name_en":"star jump (male)","name_ar":"\u0642\u0641\u0632\u0629 \u0627\u0644\u0646\u062c\u0645\u0629 (\u0630\u0643\u0631)","match_names":["star jump (male)"],"muscle":"cardio","equipment":"bodyweight","aliases":["star jump (male)"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart and your arms by your sides.\nBend your knees slightly and jump up explosively.\nAs you jump, spread your legs and extend your arms out to the sides, forming a star shape with your body.\nLand softly on the balls of your feet with your knees slightly bent.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u0630\u0631\u0627\u0639\u064a\u0643 \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u064a\u0643.\n\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u0627 \u0648\u0627\u0644\u0642\u0641\u0632 \u0628\u0634\u0643\u0644 \u0645\u062a\u0641\u062c\u0631.\n\u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0642\u0641\u0632\u060c \u0627\u0641\u0631\u062f \u0633\u0627\u0642\u064a\u0643 \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646\u060c \u0644\u062a\u0634\u0643\u0644 \u0634\u0643\u0644 \u0646\u062c\u0645\u0629 \u0628\u062c\u0633\u0645\u0643.\n\u0627\u0647\u0628\u0637 \u0628\u0647\u062f\u0648\u0621 \u0639\u0644\u0649 \u0645\u0634\u0637 \u0642\u062f\u0645\u064a\u0643 \u0645\u0639 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3223","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","stat