9 \u0627\u0644\u062f\u0648\u0627\u0633\u0627\u062a \u0648\u062b\u0628\u062a\u0647\u0645\u0627 \u0628\u0627\u0644\u0623\u0634\u0631\u0637\u0629 \u0625\u0630\u0627 \u0643\u0627\u0646\u062a \u0645\u062a\u0648\u0641\u0631\u0629.\n\u0627\u0628\u062f\u0623 \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u062f\u0648\u0627\u0633\u0627\u062a \u0628\u0648\u062a\u064a\u0631\u0629 \u0645\u0631\u064a\u062d\u0629\u060c \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0646\u0634\u0627\u0637\u0643 \u0627\u0644\u0623\u0633\u0627\u0633\u064a.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0625\u064a\u0642\u0627\u0639 \u062b\u0627\u0628\u062a \u0648\u0642\u0645 \u0628\u0632\u064a\u0627\u062f\u0629 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0645\u0642\u0627\u0648\u0645\u0629 \u0625\u0630\u0627 \u0631\u063a\u0628\u062a \u0641\u064a \u0630\u0644\u0643.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u062f\u0648\u0627\u0633\u0627\u062a \u0644\u0644\u0645\u062f\u0629 \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u0629 \u0645\u0646 \u062a\u0645\u0631\u064a\u0646 \u0627\u0644\u0642\u0644\u0628.\n\u0642\u0645 \u0628\u0627\u0644\u062a\u0647\u062f\u0626\u0629 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062a\u0642\u0644\u064a\u0644 \u0648\u062a\u064a\u0631\u0629 \u0648\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0645\u0642\u0627\u0648\u0645\u0629 \u0644\u062f\u064a\u0643 \u062a\u062f\u0631\u064a\u062c\u064a\u064b\u0627.\n\u0642\u0645 \u0628\u062a\u0645\u062f\u064a\u062f \u0639\u0636\u0644\u0627\u062a \u0633\u0627\u0642\u064a\u0643 \u0628\u0639\u062f \u0627\u0644\u062a\u0645\u0631\u064a\u0646 \u0644\u0645\u0646\u0639 \u0627\u0644\u0634\u062f \u0648\u062a\u0639\u0632\u064a\u0632 \u0627\u0644\u062a\u0639\u0627\u0641\u064a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0798","lice